referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const object = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
  const clone = (v) => JSON.parse(JSON.stringify(v));
  const merge = (a, b) => {
    if (!object(a) || !object(b)) return clone(b);
    const out = clone(a);
    for (const k of Object.keys(b)) out[k] = Object.hasOwn(a, k) ? merge(a[k], b[k]) : clone(b[k]);
    return out;
  };
  return merge(d.left, d.right);
}

