type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const object = (v: any): boolean => v !== null && typeof v === "object" && !Array.isArray(v);
  const clone = (v: any): any => JSON.parse(JSON.stringify(v));
  const merge = (a: any, b: any): any => {
    if (!object(a) || !object(b)) return clone(b);
    const out = clone(a);
    for (const k of Object.keys(b)) out[k] = Object.hasOwn(a, k) ? merge(a[k], b[k]) : clone(b[k]);
    return out;
  };
  return merge(d.left, d.right);
}
